// javaLongDecodeHex is Long.decode("0x" + p) for a component p of UUID.fromString.
func javaLongDecodeHex(p string) (int64, bool) {
	if p == "" || p[0] == '+' || p[0] == '-' { // empty -> NumberFormatException; sign after 0x -> "Sign character in wrong position"
		return 0, false
	}
	var v uint64
	for _, r := range p {
		if r > 0xFFFF { // Java parses UTF-16 chars; a surrogate is never a digit
			return 0, false
		}
		d := javaHexDigit(r)
		if d < 0 {
			return 0, false
		}
		v = v*16 + uint64(d)
		if v > 1<<63-1 { // Long overflow -> NumberFormatException
			return 0, false
		}
	}
	return int64(v), true
}

func uuidString(msb, lsb int64) string {
	m, l := uint64(msb), uint64(lsb)
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", m>>32, (m>>16)&0xffff, m&0xffff, l>>48, l&0xffffffffffff)
}

// SpringUUID converts a path variable or request parameter the way Spring's StringToUUIDConverter
// (trim, then java.util.UUID.fromString of Java 8) does. It returns the canonical lower-case text.
func SpringUUID(s string) (string, bool) {
	s = javaTrim(s)
	if s == "" {
		return "", false
	}
	parts := strings.Split(s, "-")
	for len(parts) > 0 && parts[len(parts)-1] == "" { // String.split drops trailing empty strings
		parts = parts[:len(parts)-1]
	}
	if len(parts) != 5 {
		return "", false
	}
	var c [5]int64
	for i, p := range parts {
		v, ok := javaLongDecodeHex(p)
		if !ok {
			return "", false
		}
		c[i] = v
	}
	// Java 8 does not mask the components: oversized values overlap their neighbours.
	msb := c[0]
	msb <<= 16
	msb |= c[1]
	msb <<= 16
	msb |= c[2]
	lsb := c[3]
	lsb <<= 48
	lsb |= c[4]
	return uuidString(msb, lsb), true
}

// JacksonUUID parses a JSON string value the way Jackson's UUIDDeserializer does: trimmed; either the
// 36 character form (ASCII hex, any case, dashes at 8/13/18/23) or 24 characters of Base64 encoding 16 bytes.
func JacksonUUID(s string) (string, bool) {
	s = javaTrim(s)
	switch len(s) {
	case 36:
		for i := 0; i < 36; i++ {
			c := s[i]
			if i == 8 || i == 13 || i == 18 || i == 23 {
				if c != '-' {
					return "", false
				}
				continue
			}
			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
				return "", false
			}
		}
		return strings.ToLower(s), true
	case 24:
		b, err := base64.StdEncoding.DecodeString(s)
		if err != nil || len(b) != 16 {
			return "", false
		}
		var msb, lsb int64
		for i := 0; i < 8; i++ {
			msb = msb<<8 | int64(b[i])
			lsb = lsb<<8 | int64(b[8+i])
		}
		return uuidString(msb, lsb), true
	}
	return "", false
}
